INSERT INTO "festivals" VALUES('Q11396697','別府八湯温泉まつり','Beppu Hatto Onsen Festival',NULL,NULL,NULL,NULL,NULL,'大分県','kyushu',NULL,NULL,NULL,NULL,NULL,NULL,'https://ja.wikipedia.org/wiki/%E5%88%A5%E5%BA%9C%E5%85%AB%E6%B9%AF%E6%B8%A9%E6%B3%89%E3%81%BE%E3%81%A4%E3%82%8A',NULL,60,'pending',NULL,NULL,NULL,NULL,NULL,'2026-05-20T15:07:52.470287+00:00','wikidata','2026-08-11 08:17:29',NULL,NULL,NULL,'毎年4月1日〜4月3日','{"type": "range_fixed", "month": 4, "day": 1, "end_month": 4, "end_day": 3, "raw": "4月1日から3日", "ctx": "週末を中心にイベントが開催される、別府八湯の豊かな温泉の恵みに感謝するお祭り。 4月1日から3日間は市内の100以上の共同温泉が無料開放され、商店街には温泉神社の神輿が繰り出し", "pos": 94}','週末を中心にイベントが開催される、別府八湯の豊かな温泉の恵みに感謝するお祭り。 4月1日から3日間は市内の100以上の共同温泉が無料開放され、商店街には温泉神社の神輿が繰り出し','rule_only','ok','');
