INSERT INTO "festivals" VALUES('Q17225609','おべっさん',NULL,NULL,NULL,NULL,NULL,NULL,'京都府',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'https://ja.wikipedia.org/wiki/%E3%81%8A%E3%81%B9%E3%81%A3%E3%81%95%E3%82%93',NULL,35,'pending',NULL,NULL,NULL,NULL,NULL,'2026-05-20T15:07:52.470287+00:00','wikidata','2026-08-11 10:43:07',NULL,NULL,NULL,'毎年8月20日','{"type": "fixed", "month": 8, "day": 20, "raw": "8月20日", "ctx": "おべっさんは、京都府与謝郡伊根町で毎年8月20日に行われる祭礼である。海上安全や豊漁を祈願する。伊根祭と共に伊根町の伊根地区で行", "pos": 19}','おべっさんは、京都府与謝郡伊根町で毎年8月20日に行われる祭礼である。海上安全や豊漁を祈願する。伊根祭と共に伊根町の伊根地区で行','rule_only','ok','');
