INSERT INTO "festivals" VALUES('Q21654085','日本一はっとフェスティバル',NULL,NULL,NULL,NULL,NULL,NULL,'宮城県','tohoku',38.69114167,141.18868333,NULL,NULL,NULL,NULL,'https://ja.wikipedia.org/wiki/%E6%97%A5%E6%9C%AC%E4%B8%80%E3%81%AF%E3%81%A3%E3%81%A8%E3%83%95%E3%82%A7%E3%82%B9%E3%83%86%E3%82%A3%E3%83%90%E3%83%AB',NULL,45,'pending',NULL,NULL,NULL,NULL,NULL,'2026-05-20T15:07:52.470287+00:00','wikidata','2026-08-11 13:44:56',NULL,NULL,NULL,'毎年12月第1日曜日','{"type": "nth_dow", "month": 12, "nth": 1, "dow": 6, "raw": "12月の第1日曜日", "ctx": "っとフェスティバル事務局（登米市役所 産業経済部商工観光課内）   == 期日 == 毎年12月の第1日曜日   == 駐車場 == 無料駐車場はあるが、参加者数に対し", "pos": 480}','っとフェスティバル事務局（登米市役所 産業経済部商工観光課内）   == 期日 == 毎年12月の第1日曜日   == 駐車場 == 無料駐車場はあるが、参加者数に対し','rule_only','ok','全文抽出(step97)');
