INSERT INTO "festivals" VALUES('Q11455990','富士山御神火まつり','Fujisan Gojinka Matsuri',NULL,NULL,'Q653180','富士山本宮浅間大社','Fujisan Hongū Sengen Taisha','静岡県','chubu',NULL,NULL,1984,NULL,NULL,NULL,'https://ja.wikipedia.org/wiki/%E5%AF%8C%E5%A3%AB%E5%B1%B1%E5%BE%A1%E7%A5%9E%E7%81%AB%E3%81%BE%E3%81%A4%E3%82%8A',NULL,60,'pending',NULL,NULL,NULL,NULL,NULL,'2026-05-20T15:07:52.470287+00:00','wikidata','2026-08-11 08:17:29',NULL,NULL,NULL,'毎年8月第1土曜日','{"type": "nth_dow", "month": 8, "nth": 1, "dow": 5, "raw": "8月の第1土曜日", "ctx": "富士山御神火まつり（ふじさんごじんかまつり）は、静岡県富士宮市で毎年8月の第1土曜日に開催される祭り。富士山頂で灯された火が市街地に運ばれ、その火を神輿に灯して行わ", "pos": 34}','富士山御神火まつり（ふじさんごじんかまつり）は、静岡県富士宮市で毎年8月の第1土曜日に開催される祭り。富士山頂で灯された火が市街地に運ばれ、その火を神輿に灯して行わ','rule_only','ok','');
