INSERT INTO "festivals" VALUES('Q11579109','登別地獄まつり','Noboribetsu Jigoku Matsuri',NULL,NULL,'Q3888689','登別温泉','Noboribetsu Onsen',NULL,NULL,NULL,NULL,1964,NULL,NULL,NULL,'https://ja.wikipedia.org/wiki/%E7%99%BB%E5%88%A5%E5%9C%B0%E7%8D%84%E3%81%BE%E3%81%A4%E3%82%8A',NULL,60,'pending',NULL,NULL,NULL,NULL,NULL,'2026-05-20T15:07:52.470287+00:00','wikidata','2026-08-11 08:17:29',NULL,NULL,NULL,'毎年8月最終土曜日','{"type": "last_dow", "month": 8, "dow": 5, "raw": "8月の最終土曜日", "ctx": "登別地獄まつり（のぼりべつじごくまつり）とは毎年8月の最終土曜日・日曜日に、登別温泉の地獄谷から地獄の釜のふたが開いて、閻魔（えんま）大王が鬼た", "pos": 24}','登別地獄まつり（のぼりべつじごくまつり）とは毎年8月の最終土曜日・日曜日に、登別温泉の地獄谷から地獄の釜のふたが開いて、閻魔（えんま）大王が鬼た','rule_only','ok','');
